/**
 * @name Symlink attack vulnerability in filelock
 * @description User-controlled input reaching file operations without symlink protection
 * @kind path-problem
 * @problem.severity error
 * @id py/symlink-attack-taint
 * @tags security
 *        external/cwe/cwe-061
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module SymlinkConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // Check for file open/create operations
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember(["open", "fdopen", "remove", "unlink", "rename"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pathlib").getMember("Path").getACall() and
      sink = call.getArg(0)
    )
  }
}

module SymlinkFlow = TaintTracking::Global<SymlinkConfig>;
import SymlinkFlow::PathGraph

from SymlinkFlow::PathNode source, SymlinkFlow::PathNode sink
where SymlinkFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential symlink attack from $@.", source.getNode(), "user input"
